UPDATE sys_report_dashboard SET dashboard_name = #{record.dashboardName}, remark = #{record.remark},
    version = version + 1, update_by = #{record.updateBy}, update_time = CURRENT_TIMESTAMP
WHERE tenant_id = #{record.tenantId} AND dashboard_id = #{record.dashboardId} AND owner_id = #{record.ownerId}
    AND deleted = 0 AND version = #{expectedVersion}
